{"content":""""Headless terminal backed by a real interactive bash on a pty.

Mimics a terminal where a user types characters and hits Enter:
- process starts as an interactive bash shell (``bash -i``) so startup
  files such as ``~/.bashrc`` are sourced,
- keystrokes (including control characters like ``\\x03`` for Ctrl-C)
  are written to the pty master so the kernel line discipline handles
  signals / job control exactly like a real terminal,
- interactive/fullscreen programs work because stdin/stdout/stderr are
  all attached to the pty slave with a valid TERM and window size.
"""

from __future__ import annotations

import errno
import fcntl
import os
import pty
import select
import signal
import struct
import termios
import threading
import time

from base_terminal import BaseTerminal


class HeadlessTerminal(BaseTerminal):
    """A headless interactive bash terminal controlled via keystrokes.

    Example:
        from headless_terminal import HeadlessTerminal

        term = HeadlessTerminal()
        term.send_keystrokes("echo hello\n", wait_sec=0.5)
        print(term.get_output())
        term.close()
    """

    def __init__(
        self,
        cols: int = 80,
        rows: int = 24,
        shell: str = "/bin/bash",
        cwd: str | None = None,
        env: dict | None = None,
        startup_delay: float = 0.5,
        term: str | None = None,
    ) -> None:
        self._cols = int(cols)
        self._rows = int(rows)
        self._shell = shell
        self._cwd = cwd
        self._startup_delay = float(startup_delay or 0.0)
        self._term = term or os.environ.get("TERM", "xterm-256color")

        # Build environment for the shell.
        full_env = dict(os.environ)
        if env:
            full_env.update(env)
        full_env["TERM"] = self._term
        self._env = full_env

        master_fd, slave_fd = pty.openpty()

        # Set initial window size on the slave.
        try:
            fcntl.ioctl(
                slave_fd,
                termios.TIOCSWINSZ,
                struct.pack("HHHH", self._rows, self._cols, 0, 0),
            )
        except OSError:
            pass

        pid = os.fork()
        if pid == 0:
            # Child: become session leader, attach controlling terminal,
            # connect stdio to the slave, exec interactive bash.
            try:
                os.setsid()
                try:
                    fcntl.ioctl(slave_fd, termios.TIOCSCTTY, 0)
                except OSError:
                    pass
                os.close(master_fd)
                os.dup2(slave_fd, 0)
                os.dup2(slave_fd, 1)
                os.dup2(slave_fd, 2)
                if slave_fd > 2:
                    os.close(slave_fd)
                if self._cwd:
                    os.chdir(self._cwd)
                os.execvpe(
                    self._shell,
                    [self._shell, "-i"],
                    self._env,
                )
            except Exception:
                try:
                    os._exit(127)
                except Exception:
                    pass
            # Unreachable, but keep linters happy.
            os._exit(127)

        # Parent.
        os.close(slave_fd)
        self._pid = pid
        self._master_fd = master_fd
        self._closed = False
        self._exit_status: int | None = None

        # Make master non-blocking.
        try:
            flags = fcntl.fcntl(self._master_fd, fcntl.F_GETFL)
            fcntl.fcntl(self._master_fd, fcntl.F_SETFL, flags | os.O_NONBLOCK)
        except OSError:
            pass

        self._buf_lock = threading.Lock()
        self._buf = bytearray()
        self._reader_stop = threading.Event()
        self._reader_thread = threading.Thread(
            target=self._reader_loop, name="headless-terminal-reader", daemon=True
        )
        self._reader_thread.start()

        # Give interactive bash a moment to source startup files
        # (~/.bashrc etc.) and print the first prompt.
        if self._startup_delay > 0:
            time.sleep(self._startup_delay)

    # ------------------------------------------------------------------
    # BaseTerminal API
    # ------------------------------------------------------------------
    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        """Send keystrokes to the terminal.

        Args:
            keystrokes: characters/keys to type. Control characters such
                as ``"\\x03"`` (Ctrl-C), ``"\\x04"`` (Ctrl-D),
                ``"\\x1a"`` (Ctrl-Z) are passed through the pty so the
                kernel generates SIGINT/SIGTSTP etc. like a real terminal.
                A trailing ``"\\n"`` acts as hitting Enter.
            wait_sec: seconds to wait after sending for the command to
                complete.
        """
        if self._closed:
            raise OSError("terminal is closed")
        if isinstance(keystrokes, bytes):
            data = bytes(keystrokes)
        elif isinstance(keystrokes, str):
            data = keystrokes.encode("utf-8")
        else:
            data = str(keystrokes).encode("utf-8")
        if data:
            self._write_all(data)
        if wait_sec and wait_sec > 0:
            time.sleep(float(wait_sec))

    # ------------------------------------------------------------------
    # Helpers (extra convenience; not part of BaseTerminal contract)
    # ------------------------------------------------------------------
    def get_output(self) -> str:
        """Return all output captured so far, decoded as text."""
        with self._buf_lock:
            raw = bytes(self._buf)
        return raw.decode("utf-8", errors="replace")

    def get_output_bytes(self) -> bytes:
        """Return all output captured so far as raw bytes."""
        with self._buf_lock:
            return bytes(self._buf)

    def read_available(self) -> str:
        """Alias for :meth:`get_output`."""
        return self.get_output()

    def read_all(self) -> str:
        """Alias for :meth:`get_output`."""
        return self.get_output()

    def read(self, timeout: float = 0.0) -> str:  # noqa: A003 - convenience name
        """Optionally wait, then return captured output."""
        if timeout and timeout > 0:
            time.sleep(float(timeout))
        return self.get_output()

    def snapshot(self) -> str:
        """Alias for :meth:`get_output`."""
        return self.get_output()

    def get_screen(self) -> str:
        """Alias for :meth:`get_output`."""
        return self.get_output()

    @property
    def output(self) -> str:
        """Captured output so far."""
        return self.get_output()

    def clear(self) -> None:
        """Discard buffered output captured so far."""
        with self._buf_lock:
            self._buf.clear()

    def wait_for(self, text: str, timeout: float = 10.0, poll_interval: float = 0.05) -> bool:
        """Wait until ``text`` appears in the output. Returns True/False."""
        deadline = time.time() + float(timeout)
        while time.time() < deadline:
            if text in self.get_output():
                return True
            if not self.is_alive() and text in self.get_output():
                return True
            time.sleep(poll_interval)
        return text in self.get_output()

    def expect(self, text: str, timeout: float = 10.0) -> bool:
        """Alias for :meth:`wait_for`."""
        return self.wait_for(text, timeout=timeout)

    def resize(self, cols: int, rows: int) -> None:
        """Resize the pty window (supports fullscreen interactive apps)."""
        self._cols = int(cols)
        self._rows = int(rows)
        try:
            fcntl.ioctl(
                self._master_fd,
                termios.TIOCSWINSZ,
                struct.pack("HHHH", self._rows, self._cols, 0, 0),
            )
        except OSError:
            pass
        try:
            os.kill(self._pid, signal.SIGWINCH)
        except OSError:
            pass

    # Backwards/forwards compatible alias names.
    set_size = resize
    set_winsize = resize

    def is_alive(self) -> bool:
        """Return True if the shell process is still running."""
        if self._closed:
            return False
        try:
            pid, _status = os.waitpid(self._pid, os.WNOHANG)
        except ChildProcessError:
            return False
        except OSError:
            return False
        if pid == 0:
            return True
        return False

    def poll(self) -> int | None:
        """Return exit status if the shell exited, else None."""
        try:
            pid, status = os.waitpid(self._pid, os.WNOHANG)
        except ChildProcessError:
            return self._exit_status
        except OSError:
            return self._exit_status
        if pid == 0:
            return None
        if os.WIFEXITED(status):
            self._exit_status = os.WEXITSTATUS(status)
        elif os.WIFSIGNALED(status):
            self._exit_status = -os.WTERMSIG(status)
        else:
            self._exit_status = status
        return self._exit_status

    def close(self) -> None:
        """Terminate the shell and release the pty."""
        if self._closed:
            return
        self._closed = True
        self._reader_stop.set()
        # Best effort: ask the shell to exit, then kill the process group.
        try:
            self._write_all(b"exit\n")
        except OSError:
            pass
        time.sleep(0.1)
        try:
            os.killpg(os.getpgid(self._pid), signal.SIGHUP)
        except OSError:
            try:
                os.kill(self._pid, signal.SIGHUP)
            except OSError:
                pass
        time.sleep(0.2)
        if self.is_alive():
            try:
                os.killpg(os.getpgid(self._pid), signal.SIGKILL)
            except OSError:
                try:
                    os.kill(self._pid, signal.SIGKILL)
                except OSError:
                    pass
        try:
            os.close(self._master_fd)
        except OSError:
            pass
        # Reap the child if it exited.
        try:
            while True:
                try:
                    pid, status = os.waitpid(self._pid, os.WNOHANG)
                except ChildProcessError:
                    break
                except OSError as exc:
                    if exc.errno in (errno.ECHILD, errno.ESRCH):
                        break
                    break
                if pid == 0:
                    break
                if os.WIFEXITED(status):
                    self._exit_status = os.WEXITSTATUS(status)
                elif os.WIFSIGNALED(status):
                    self._exit_status = -os.WTERMSIG(status)
                break
        except OSError:
            pass

    # Aliases so callers using different names still work.
    terminate = close
    kill = close
    shutdown = close

    def __enter__(self) -> "HeadlessTerminal":
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.close()

    def __del__(self) -> None:
        try:
            self.close()
        except Exception:
            pass

    # ------------------------------------------------------------------
    # Internals
    # ------------------------------------------------------------------
    def _write_all(self, data: bytes) -> None:
        view = memoryview(data)
        offset = 0
        while offset < len(data):
            try:
                _, writable, _ = select.select([], [self._master_fd], [], 5.0)
            except (OSError, ValueError):
                raise OSError("terminal is closed")
            if not writable:
                raise TimeoutError("timed out writing to terminal")
            try:
                n = os.write(self._master_fd, view[offset:])
            except OSError as exc:
                if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK):
                    time.sleep(0.01)
                    continue
                if exc.errno == errno.EIO:
                    raise OSError("terminal is closed")
                raise
            if n is None or n == 0:
                time.sleep(0.01)
                continue
            offset += n

    def _reader_loop(self) -> None:
        while not self._reader_stop.is_set():
            try:
                readable, _, _ = select.select([self._master_fd], [], [], 0.2)
            except (OSError, ValueError):
                break
            if not readable:
                # Check whether the child has exited; if so, drain then stop.
                try:
                    pid, _ = os.waitpid(self._pid, os.WNOHANG)
                    if pid != 0:
                        self._drain()
                        break
                except (ChildProcessError, OSError):
                    pass
                continue
