                chunk = os.read(self._master_fd, 65536)
            except OSError as exc:
                if exc.errno in (errno.EAGAIN, errno.EWOULDBLOCK):
                    continue
                # EIO means the slave side is gone (child exited).
                break
            except ValueError:
                break
            if not chunk:
                break
            with self._buf_lock:
                self._buf.extend(chunk)
                # Bound memory: keep the last ~5MB.
                if len(self._buf) > 5 * 1024 * 1024:
                    del self._buf[: len(self._buf) - 5 * 1024 * 1024]
        # Final drain attempt.
        self._drain()

    def _drain(self) -> None:
        for _ in range(20):
            try:
                chunk = os.read(self._master_fd, 65536)
            except OSError:
                break
            except ValueError:
                break
            if not chunk:
                break
            with self._buf_lock:
                self._buf.extend(chunk)
